# JQL 예시: 내가 담당하고 상태가 In Progress인 이슈 검색
# project = MYPROJ AND assignee = currentUser() AND status = "In Progress"

# REST API로 이슈 MYPROJ-123을 "Done" 상태로 전환
curl -X POST \
  https://your-domain.atlassian.net/rest/api/3/issue/MYPROJ-123/transitions \
  -H "Authorization: Basic $TOKEN" \
  -H "Content-Type: application/json" \
  -d '{
    "transition": {
      "id": "31"
    }
  }'
